document.head.insertAdjacentHTML("beforeend", "<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/400.css\">\n<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/700.css\">");
document.body.insertAdjacentHTML("afterbegin", "<div id=\"intro\">\n<div class=\"pv\"><video controls playsinline preload=\"none\" poster=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/pv-poster.webp\"><source src=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/pv.webm\" type='video/webm; codecs=\"av01.0.08M.10, opus\"'><source src=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/pv.mp4\" type=\"video/mp4\"></video></div>\n<div class=\"seam\"></div>\n<div class=\"main\">\n<p class=\"lead\">毕业季，你和女友洛槿、她的同学祝凛，跟着瑞典闺蜜莉妮娅飞往瑞典中部的哈尔辛兰。山谷深处的哈尔加村，今年夏至要办九十年一次的盛宴，白夜不落，人人换上亲手织的白色亚麻衣裙，绕着五月柱起舞。接下来每一步怎么走，由你来定。</p>\n<h2>她们</h2>\n<div class=\"who\" id=\"who\"></div>\n<p class=\"say\" id=\"say\"></p>\n<h2>怎么玩</h2>\n<div class=\"grid g4\">\n<div class=\"cell\" style=\"--c:#E8B923\"><span class=\"t\">时间</span>抵达日加九天，每天分上午、下午、傍晚、夜里四个时段，每回合最多推进一个时段。</div>\n<div class=\"cell\" style=\"--c:#D8452F\"><span class=\"t\">地点</span>先是机场、路上、村外草地，入村以后在 17 处地点之间走动，处处有场景图。</div>\n<div class=\"cell\" style=\"--c:#E48AA3\"><span class=\"t\">节目</span>盛宴每天都有排好的节目按时到来，重要的大场面配一张大图。</div>\n<div class=\"cell\" style=\"--c:#27407A\"><span class=\"t\">行动</span>想做什么、说什么，直接写进输入框；也可以点回复末尾的四个选项。</div>\n</div>\n<h2>回复末尾的功能栏</h2>\n<div class=\"grid g3\">\n<div class=\"cell\" style=\"--c:#E8B923\"><span class=\"t\">日程</span>今天的民俗小科普与四个时段的安排。</div>\n<div class=\"cell\" style=\"--c:#3F6FB5\"><span class=\"t\">地图</span>村子俯瞰图，点圆点看场景图与介绍。</div>\n<div class=\"cell\" style=\"--c:#E48AA3\"><span class=\"t\">立绘</span>五位女主的介绍、四问四答与立绘。</div>\n</div>\n<p class=\"note\">运行需要安装酒馆助手与提示词模板。回复结尾的变量由系统自动维护，弹出「变量发生错误」时重新生成本楼即可。</p>\n<div class=\"go\"><button id=\"go\">进入开场</button><span class=\"hint\">也可以点消息框的右箭头，切换到下一条开场白</span></div>\n<p class=\"credit\">制卡 ssd（类脑 @buyssdcom），保留一切权利</p>\n</div>\n</div>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{overflow:hidden}\nbody{font-family:\"Noto Serif SC\",\"Source Han Serif SC\",\"Songti SC\",\"STSong\",\"SimSun\",serif;font-size:14px;line-height:1.7;color:#27302A;background:transparent}\n#intro{background:#FBFAF6;border:1px solid #E2DFD3;border-radius:12px;overflow:hidden}\n.pv{aspect-ratio:16/9;background:#000}\n.pv video{display:block;width:100%;height:100%}\n.seam{height:4px;background:linear-gradient(90deg,#5E7E44,#E8B923,#D8452F,#E48AA3,#8A6CB4,#3F6FB5)}\n.main{padding:16px 18px 18px}\n.lead{font-size:14px;line-height:1.95;text-align:justify}\nh2{margin:20px 0 10px;font-size:15px;letter-spacing:.14em}\n.who{display:flex;justify-content:center;gap:16px}\n.who button{display:flex;flex-direction:column;align-items:center;gap:6px;border:0;background:none;font:inherit;font-size:12.5px;letter-spacing:.08em;color:#6B7166;cursor:pointer}\n.who i{width:64px;aspect-ratio:1;border:2px solid var(--c);border-radius:50%;background:var(--img) var(--pos)/200% auto no-repeat;opacity:.78;filter:saturate(.75);transition:opacity .2s,filter .2s,transform .2s,box-shadow .2s}\n.who button:hover i{opacity:.85}\n.who button.on{font-weight:700;color:var(--c)}\n.who button.on i{opacity:1;filter:none;transform:scale(1.08);box-shadow:0 0 0 4px color-mix(in srgb,var(--c) 22%,transparent)}\n.say{min-height:5.6em;margin-top:12px;padding:10px 14px;border-top:3px solid var(--c);border-radius:0 0 8px 8px;background:#FFFFFF;font-size:13.5px;line-height:1.85;text-align:justify;transition:border-color .2s}\n.grid{display:grid;gap:8px}\n.g4{grid-template-columns:repeat(2,1fr)}\n.g3{grid-template-columns:repeat(3,1fr)}\n.cell{padding:9px 12px 10px;border-top:3px solid var(--c);border-radius:0 0 8px 8px;background:#FFFFFF;font-size:12.5px;line-height:1.75}\n.cell .t{display:block;margin-bottom:2px;font-size:13.5px;font-weight:700;letter-spacing:.1em;color:var(--c)}\n.note{margin-top:14px;font-size:12px;line-height:1.75;color:#6B7166}\n.go{display:flex;flex-direction:column;align-items:center;gap:8px;margin-top:18px}\n#go{padding:9px 44px;border:0;border-radius:8px;background:#5E7E44;font:inherit;font-size:16px;letter-spacing:.3em;text-indent:.3em;color:#fff;cursor:pointer;transition:filter .15s}\n#go:hover{filter:brightness(1.1)}\n.hint{font-size:12px;color:#6B7166}\n.credit{margin-top:14px;font-size:11.5px;letter-spacing:.06em;text-align:center;color:#6B7166}\n@media (max-width:520px){.main{padding:14px 12px 16px}.lead{font-size:13px;line-height:1.9}.who{gap:8px}.who i{width:52px}.who button{font-size:12px}.say{font-size:13px;min-height:7.4em}.g3{grid-template-columns:1fr}.cell{font-size:12px}}\n</style>");
// 每人：名字、花色、立绘、头像里脸的位置（立绘放大一倍后的背景定位）、一句介绍
const GIRLS = [
  ['洛槿', '#D8452F', 'https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/portrait-luo-jin-ru-cun.webp', '46% 9%', '你交往一年半的女友，人类学大三。安静敏感，总是最先察觉谁的情绪不对；熟了以后爱说爱笑，也爱和你闹。'],
  ['莉妮娅', '#E8B923', 'https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/portrait-li-ni-ya-ru-cun.webp', '46% 9%', '洛槿无话不谈的瑞典闺蜜，在哈尔加长大，也是这次邀你们回村的人。说话慢，爱听人说话，笑起来眼睛弯。'],
  ['布丽塔', '#E48AA3', 'https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/portrait-bu-li-ta-ri-chang.webp', '46% 12%', '哈尔加的姑娘，莉妮娅从小带大的妹妹。直率热情，喜欢谁就让谁知道，对外面的世界有问不完的问题。'],
  ['艾拉', '#8A6CB4', 'https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/portrait-ai-la-hui-cun.webp', '46% 9%', '哈尔加的药草师，在外面生活过几年，这个夏天回村过节。沉静温柔，说话轻，总在恰好的时候出现。'],
  ['祝凛', '#3F6FB5', 'https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@main/assets/portrait-zhu-lin-ru-cun.webp', '46% 9%', '人类学大四，毕业论文写的就是瑞典的仲夏节。大小姐出身，言谈有分寸，一聊到民俗就两眼放光，在队伍里是最靠谱的一个。'],
];
const who = document.getElementById('who'), say = document.getElementById('say');
who.innerHTML = GIRLS.map(([name, c, pic, pos], i) => '<button data-i="' + i + '" style="--c:' + c + ';--img:url(' + pic + ');--pos:' + pos + '"><i></i>' + name + '</button>').join('');
const pick = (i) => {
  who.querySelectorAll('button').forEach((b, j) => b.classList.toggle('on', i === j));
  say.style.setProperty('--c', GIRLS[i][1]);
  say.textContent = GIRLS[i][4];
};
who.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) pick(+b.dataset.i); });
pick(0);
document.getElementById('go').addEventListener('click', () => triggerSlash('/swipe'));
